function a(r){return(r||"").split(",").map(t=>{const[e,...s]=t.trim().split(";"),n=s.map(i=>i.trim()).find(i=>i.startsWith("q="));return{tag:e,q:n?Number(n.slice(2)):1}}).filter(t=>t.tag&&t.tag!=="*"&&t.q>0).sort((t,e)=>e.q-t.q).map(t=>t.tag).slice(0,5)}async function c(r,t){const e=r.headers,s={langs:a(e.get("accept-language")),served:t.served,country:e.get("x-vercel-ip-country")||e.get("cf-ipcountry")||void 0,route:new URL(r.url).pathname,event:t.event,arm:t.arm};try{const n=await fetch(`${t.endpoint}/api/insights/${t.key}`,{method:"POST",body:JSON.stringify(s)});return n.ok?await n.json():null}catch{return null}}export{a as acceptLanguages,c as reportVisit};
